import json
import streamlit as st
import streamlit.components.v1 as components

@st.cache_data(show_spinner=False)
def game_html():
    raw = base64.b64decode(_PAYLOAD)
    archive = zipfile.ZipFile(io.BytesIO(raw))
    assets = {}
    for name in archive.namelist():
        if name in ('index.html', 'game.js'):
            continue
        mime = mimetypes.guess_type(name)[0] or 'application/octet-stream'
        assets[name] = 'data:' + mime + ';base64,' + base64.b64encode(archive.read(name)).decode('ascii')
    bootstrap = '''<script>
    window.__knightAssets = ASSETS;
    const originalFetch = window.fetch.bind(window);
    window.fetch = (input, init) => {
      const raw = typeof input === 'string' ? input : input.url;
      const key = raw.replace(/^\\.\\//, '').replace(/^\\//, '');
      return originalFetch(window.__knightAssets[key] || input, init);
    };
    </script>'''.replace('ASSETS', json.dumps(assets))
    html = archive.read('index.html').decode('utf-8')
    for name in ('source.zip', 'LICENSE'):
        html = html.replace('href="' + name + '"', 'download="' + name + '" href="' + assets[name] + '"')
    js = archive.read('game.js').decode('utf-8').replace('</script', '<\\/script')
    return html.replace('<script src="game.js"></script>', bootstrap + '<script>' + js + '</script>')

def main():
    st.set_page_config(page_title='기사 패턴 · UnderRune', page_icon='⚔️', layout='wide')
    st.caption('기사 패턴 16종 · 갑옷 두 슬롯 · PC / 모바일 조작 지원')
    components.html(game_html(), height=1450, scrolling=True)

if __name__ == '__main__':
    main()
